// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// Helios placeholder (HBC+ v1.0)
// HBC+ keeps 'Helios' in the strategy list for a future HELIOS integration, but the HELIOS
// flow itself is not part of HBC+. Without this tab, selecting 'Helios' would make
// Home Battery Start fail on a link call with no target, and the batteries would keep their
// last setpoint. This placeholder runs Full stop instead and warns (at most every 10 min).
// Delete this tab before you import a real HELIOS flow: two 'Helios' link-in nodes make
// the dynamic link call ambiguous.
const log = (global.get('logger') || (() => {}));
const now = Date.now();
if (now - (context.get('lastWarn') || 0) > 600000) {
    context.set('lastWarn', now);
    if (log) log(this, "**Helios** selected, but the HELIOS flow is not installed - running Full stop", "warn");
}
node.status({ fill: 'yellow', shape: 'ring', text: `HELIOS not installed: Full stop (${new Date().toLocaleTimeString()})` });
msg.target = "Full stop";
RED.util.setMessageProperty(msg, "strategy.display", "Helios (not installed)", true);
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if (handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}
